  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postInit =>
        return (st"""// Begin test cases for DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postInit
                    |
                    |test(s"DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toDocked_Service_Access_Lifecycle_SupervisorIntentQualifier_supervisorProcess_intentQualifier_PostState_Container_PS(postJson).left
                    |  assert(scp_candidate.Docked_Service_Access_Lifecycle_Supervisor.IntentQualifier_supervisorProcess_intentQualifier_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
                    |// End test cases for DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postInit""")
      case scp_candidate.runtimemonitor.ObservationKind.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postCompute =>
        return (st"""// Begin test cases for DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postCompute
                    |
                    |test(s"DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postCompute: Check Post-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val preContainer = scp_candidate.JSON.toDocked_Service_Access_Lifecycle_SupervisorIntentQualifier_supervisorProcess_intentQualifier_PreState_Container_PS(preJson).left
                    |  val postContainer = scp_candidate.JSON.toDocked_Service_Access_Lifecycle_SupervisorIntentQualifier_supervisorProcess_intentQualifier_PostState_Container_PS(postJson).left
                    |  if (verbose) {
                    |    println("Pre-State Values:")
                    |    println(s"  $$preContainer")
                    |    println("Post-State Values:")
                    |    println(s"  $$postContainer");
                    |  }
                    |  assert(scp_candidate.Docked_Service_Access_Lifecycle_Supervisor.IntentQualifier_supervisorProcess_intentQualifier_GumboX.compute_CEP_Post_Container(preContainer, postContainer))
                    |}
                    |// End test cases for DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier_postCompute""")
      case scp_candidate.runtimemonitor.ObservationKind.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_dockReadinessQualifier_postInit =>
        return (st"""// Begin test cases for DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_dockReadinessQualifier_postInit
                    |
                    |test(s"DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_dockReadinessQualifier_postInit: Check Post-condition$suffix") {
